CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);INSERT OR IGNORE INTO settings VALUES('open','true'),('round','1'),('round2_candidates','[]');CREATE TABLE IF NOT EXISTS redeems(round INTEGER,nim_hash TEXT,token_hash TEXT UNIQUE,used INTEGER DEFAULT 0,redeemed_at TEXT,used_at TEXT,PRIMARY KEY(round,nim_hash));CREATE TABLE IF NOT EXISTS ballots(id TEXT PRIMARY KEY,round INTEGER,candidate_nim TEXT,created_at TEXT);